WITH flagged AS (SELECT *, CASE WHEN event_time - LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) > INTERVAL 14 DAYS THEN 1 ELSE 0 END AS is_new_session FROM web_events), sessions_web_events AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged) SELECT DATE_TRUNC('QUARTER', event_time) AS quarter_start, island_id, APPROX_PERCENTILE(island_id, ARRAY(0.25, 0.5, 0.75)) AS island_id_quartiles, SUM(duration_sec) AS total_duration_sec, PERCENTILE_APPROX(duration_sec, 0.9) AS duration_sec_p90, MAX(event_time) AS ended_at, COUNT(*) FILTER (WHERE page = '/cart') AS cart_rows FROM sessions_web_events GROUP BY 1, 2;
